import datetime, json, pathlib, subprocess
repo = 'entireio/entire-brain'
root = pathlib.Path('/tmp/dependency-bot-prs-entire-brain-20261015')
root.mkdir(exist_ok=True)
def run(*args):
    p = subprocess.run(args, text=True, capture_output=True, timeout=90)
    if p.returncode: raise RuntimeError(p.stderr.strip() or p.stdout.strip())
    return p.stdout
def ghjson(*args): return json.loads(run('gh', *args))
fields = 'number,title,url,headRefName,headRefOid,baseRefName,isDraft,state,mergeable,mergeStateStatus,reviewDecision'
trusted = set()
for app in ['dependabot', 'renovate', 'entire-renovate-bot']:
    trusted.update(p['number'] for p in ghjson('pr','list','-R',repo,'--state','open','--limit','100','--app',app,'--json','number'))
candidates = [ghjson('pr','view',str(n),'-R',repo,'--json',fields) for n in sorted(trusted)]
ledger = {'repo':repo,'default_branch':'main','started_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'initial_candidates':candidates,'results':[]}
path = root / 'ledger.json'
def save(): path.write_text(json.dumps(ledger,indent=2)+'\n')
save()
trail_numbers = {353:268,354:269,356:271,357:272,358:273,359:274,360:275,361:276,362:277}
for initial in candidates:
    n = initial['number']; result = {'number':n,'title':initial['title'],'state':'NEEDS_ATTENTION','changes_pushed_by_agent':[]}
    try:
        p = ghjson('pr','view',str(n),'-R',repo,'--json',fields)
        result['before'] = p
        if p['state'] != 'OPEN' or p['isDraft'] or p['baseRefName'] != 'main' or p['reviewDecision'] == 'CHANGES_REQUESTED':
            raise RuntimeError('Candidate fails open/default-branch/draft/human-review eligibility')
        base = ghjson('api',f'repos/{repo}/commits/main')['sha']
        result['captured_default_sha'] = base
        comparison = ghjson('api',f'repos/{repo}/compare/{base}...{p["headRefOid"]}')['status']
        result['comparison_before'] = comparison
        if comparison not in ['ahead','identical']:
            result['update_branch_output'] = run('gh','pr','update-branch',str(n),'-R',repo).strip()
        after = ghjson('pr','view',str(n),'-R',repo,'--json',fields)
        result['after'] = after
        result['comparison_after'] = ghjson('api',f'repos/{repo}/compare/{base}...{after["headRefOid"]}')['status']
        if result['comparison_after'] not in ['ahead','identical']:
            raise RuntimeError('Updated head does not demonstrably contain captured main; no waiting or merge attempted')
        trail = ghjson_external = json.loads(run('entire','trail','show',str(trail_numbers[n]),'--repo','gh/'+repo,'--json'))
        result['trail'] = {'url':trail['url'],'status':trail['status'],'head':trail.get('mergeability',{}).get('head_sha'),'gates':[{'key':g.get('gate_key'),'state':g.get('state'),'outcome':g.get('outcome'),'evaluated_at_sha':g.get('evaluated_at_sha')} for g in trail.get('mergeability',{}).get('gates',[])]}
        result['stage'] = 'post-synchronization policy/CI gate'
        result['reason'] = 'Branch synchronized. Required human Trail approval remains unestablished; new-head safety review, native verification, CI and personal review gates not established. No merge attempted.'
        result['next_action'] = 'Complete authoritative dependency safety review and native verification on new head, obtain clean current-head CI/review evidence and required human approval, then revalidate latest main ancestry before guarded merge.'
    except Exception as e:
        result['stage'] = result.get('stage','synchronization')
        result['reason'] = str(e)
        result['next_action'] = 'Inspect synchronization/policy evidence; do not merge until all gates hold.'
    result['observed_at'] = datetime.datetime.now(datetime.timezone.utc).isoformat()
    ledger['results'].append(result); save()
    print(json.dumps(result),flush=True)
print('LEDGER='+str(path),flush=True)

