import json,subprocess,pathlib,datetime
root=pathlib.Path('/tmp/dependency-bot-prs-entire-brain-20261015')
ledger=json.loads((root/'ledger.json').read_text())
def run(*a):
 p=subprocess.run(a,text=True,capture_output=True,timeout=40)
 if p.returncode: raise RuntimeError(p.stderr.strip() or p.stdout.strip())
 return json.loads(p.stdout)
trails={353:268,354:269,356:271,357:272,358:273,359:274,360:275,361:276,362:277}
for r in ledger['results']:
 n=r['number'];t=trails[n]
 try:
  pr=run('gh','pr','view',str(n),'-R',ledger['repo'],'--json','headRefOid,state,isDraft,mergeable,mergeStateStatus,reviewDecision,statusCheckRollup')
  detail=run('entire','api','--jurisdiction','us',f'/api/v1/trails/gh/entireio/entire-brain/{t}')
  if not detail.get('head_sha') or not isinstance(detail.get('monitors'),list):raise RuntimeError('Trail detail response shape mismatch')
  findings=run('entire','trail','finding','list',str(t),'--repo','gh/'+ledger['repo'],'--freshness','any','--json')
  query='query {repository(owner:"entireio",name:"entire-brain"){pullRequest(number:'+str(n)+'){headRefOid reviewThreads(first:100){nodes{isResolved} pageInfo{hasNextPage}}}}}'
  threads=run('gh','api','graphql','-f','query='+query)['data']['repository']['pullRequest']
  checks=[c for c in pr.pop('statusCheckRollup') if c.get('name',c.get('context'))!='Partial Gates']
  failed=[{'name':c.get('name',c.get('context')),'conclusion':c.get('conclusion',c.get('state')),'url':c.get('detailsUrl',c.get('targetUrl'))} for c in checks if c.get('conclusion',c.get('state')) in ['FAILURE','ERROR','CANCELLED','TIMED_OUT','ACTION_REQUIRED']]
  pending=[c.get('name',c.get('context')) for c in checks if c.get('status') not in ['COMPLETED',None] or c.get('state') in ['PENDING','EXPECTED']]
  receipt={'observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pr':pr,'trail_url':f'https://entire.io/gh/entireio/entire-brain/trails/{t}','trail_status':detail['status'],'trail_head':detail['head_sha'],'head_matches':detail['head_sha']==pr['headRefOid'],'gates':[{'key':g.get('gate_key'),'state':g.get('state'),'outcome':g.get('outcome'),'evaluated_at_sha':g.get('evaluated_at_sha')} for g in detail.get('mergeability',{}).get('gates',[])],'main_review':[{'runner_id':x['runner_id'],'state':x.get('state'),'outcome':x.get('outcome'),'evaluated_at_sha':x.get('evaluated_at_sha')} for x in detail.get('runners',[]) if x['runner_id']=='trail-review'],'monitors':[ {k:m.get(k) for k in ['key','state','outcome','evaluating','head_sha','evaluated_at_sha','run_id','percent_value','size_value','boolean_value']} for m in detail['monitors']],'open_findings':len(findings['findings']),'findings_has_more':findings['has_more'],'unresolved_threads':sum(not x['isResolved'] for x in threads['reviewThreads']['nodes']),'threads_has_more':threads['reviewThreads']['pageInfo']['hasNextPage'],'bugbot_checks':[c for c in checks if 'bugbot' in c.get('name','').lower()],'failed':failed,'pending':pending,'total_check_count':len(checks)}
  r['latest_gate_receipt']=receipt;r['state']='NEEDS_ATTENTION';r['stage']='current-head CI/review gate';r['reason']='CI failures or pending checks; complete safety/review gate not established; no merge attempted.'
  (root/f'gate-{n}.json').write_text(json.dumps(receipt,indent=2)+'\n')
  print(json.dumps({'trail':receipt['trail_url'],'head':pr['headRefOid'],'mergeable':pr['mergeable'],'mergeStateStatus':pr['mergeStateStatus'],'open_findings':receipt['open_findings'],'unresolved_threads':receipt['unresolved_threads'],'main_review':receipt['main_review'],'failed':failed,'pending_count':len(pending),'bugbot_count':len(receipt['bugbot_checks'])}),flush=True)
 except Exception as e:
  r['reason']=str(e);print(json.dumps({'number':n,'error':str(e)}),flush=True)
 (root/'ledger.json').write_text(json.dumps(ledger,indent=2)+'\n')

