import datetime, json, pathlib, subprocess
SHA = 'fb972e5d9d14ab6e2e935fb0a083ae565b316680'
q = '''query {
 repository(owner:"entireio", name:"entire-brain") {
  defaultBranchRef {
   name target {oid}
   branchProtectionRule {requiredStatusCheckContexts}
  }
  rulesets(first:100, includeParents:true) {
   nodes {id name enforcement target}
   pageInfo {hasNextPage}
  }
  object(expression:"fb972e5d9d14ab6e2e935fb0a083ae565b316680") {
   ... on Commit {
    oid
    statusCheckRollup {
     contexts(first:100) {
      nodes {
       ... on CheckRun {
        databaseId name status conclusion detailsUrl
        checkSuite {app {slug} workflowRun {databaseId url}}
       }
       ... on StatusContext {context state targetUrl}
      }
      pageInfo {hasNextPage}
     }
    }
   }
  }
 }
}'''
p = subprocess.run(['gh','api','graphql','-f','query='+q], text=True, capture_output=True, timeout=40)
if p.returncode: raise SystemExit(p.stderr)
raw = json.loads(p.stdout)
if raw.get('errors'): raise SystemExit(json.dumps(raw['errors']))
r = raw['data']['repository']
commit = r.get('object') or {}
if commit.get('oid') != SHA: raise SystemExit('Merge-commit identity unavailable/mismatched')
contexts = (commit.get('statusCheckRollup') or {}).get('contexts') or {}
checks = [x for x in contexts.get('nodes',[]) if x.get('name',x.get('context')) != 'Partial Gates']
protection = r['defaultBranchRef'].get('branchProtectionRule')
rulesets = r['rulesets']
inventory_complete = protection is not None and not rulesets['nodes'] and not rulesets['pageInfo']['hasNextPage']
required = sorted(set((protection or {}).get('requiredStatusCheckContexts',[])) - {'Partial Gates'})
by_name = {c.get('name',c.get('context')):c for c in checks}
def passed(c):
    return (c.get('status') == 'COMPLETED' and c.get('conclusion') == 'SUCCESS') or c.get('state') == 'SUCCESS'
missing = [n for n in required if n not in by_name]
not_success = [n for n in required if n in by_name and not passed(by_name[n])]
failures = [c for c in checks if c.get('conclusion',c.get('state')) in {'FAILURE','ERROR','CANCELLED','TIMED_OUT','ACTION_REQUIRED'} and c.get('name',c.get('context')) not in {'Cursor Bugbot','Entire Gates'}]
receipt = {
 'repository':'entireio/entire-brain', 'default_branch':r['defaultBranchRef']['name'],
 'actual_merge_sha':SHA, 'observed_branch_head':r['defaultBranchRef']['target']['oid'],
 'observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),
 'required_inventory':{'complete':inventory_complete,'protection':protection,'rulesets':rulesets,'required_names':required,'source':'authenticated GitHub GraphQL'},
 'contexts_has_next_page':contexts.get('pageInfo',{}).get('hasNextPage',False),
 'checks':checks, 'missing_required':missing, 'unsuccessful_required':not_success,
 'required_success':inventory_complete and bool(required) and bool(checks) and not missing and not not_success and not contexts.get('pageInfo',{}).get('hasNextPage',False),
 'other_ordinary_failures':failures, 'cleanup_authorized':False
}
path = pathlib.Path('/Users/alex/.local/state/herdr/orchestrations/dependency-security-baseline-wPB.merge-commit-observation.json')
path.write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps({k:receipt[k] for k in ['actual_merge_sha','observed_branch_head','observed_at','required_success','missing_required','unsuccessful_required']} | {'required_count':len(required),'other_failures':[{'name':c.get('name',c.get('context')),'url':c.get('detailsUrl',c.get('targetUrl'))} for c in failures],'receipt':str(path)}))

