const out = '/Users/alex/.local/state/herdr/orchestrations/security-followups-20261017';
const lock = JSON.parse(fs.readFileSync('/private/tmp/cor2145static/actions-setup-go-b7ad1da/package-lock.json', 'utf8'));
for (const name of ['@azure/core-client', '@azure/storage-blob']) {
  const entry = lock.packages['node_modules/' + name];
  const version = entry.version;
  const response = await fetch('https://registry.npmjs.org/' + name + '/' + version);
  if (!response.ok) throw Error('metadata HTTP ' + response.status);
  const meta = await response.json();
  const url = new URL(meta.dist.tarball);
  if (url.protocol !== 'https:' || url.hostname !== 'registry.npmjs.org') throw Error('Unexpected static data origin');
  const archive = await fetch(url);
  if (!archive.ok) throw Error('archive HTTP ' + archive.status);
