import fs from 'node:fs';
import {spawn} from 'node:child_process';
const [mode,agent,packet,result] = process.argv.slice(2);
if (!agent || !packet || !result) throw Error('delivery needs agent, packet and result paths');
if (mode === 'dispatch') {
  const p = spawn(process.execPath, [import.meta.filename,'deliver',agent,packet,result], {detached:true,stdio:'ignore'});
  p.unref();
  console.log(JSON.stringify({agent,delivery_pid:p.pid,detached:true,result,notification:'Agent work is covered by parent-owned native Herdr watch; this is delivery only'}));
} else if (mode === 'deliver') {
  const fd = fs.openSync(result+'.log','w',0o600);
  const text = fs.readFileSync(packet,'utf8');
  const p = spawn('herdr',['agent','prompt',agent,text],{stdio:['ignore',fd,fd]});
  p.on('error', e => fs.writeFileSync(result,JSON.stringify({agent,error:e.message,observed_at:new Date().toISOString()}),{mode:0o600}));
  p.on('exit',(code,signal)=>{fs.closeSync(fd);fs.writeFileSync(result,JSON.stringify({agent,code,signal,observed_at:new Date().toISOString()}),{mode:0o600});});
} else throw Error('unknown mode');

