import { readFile } from "node:fs/promises";
import { isAbsolute } from "node:path";
import type { HerdrAgentMonitorState } from "./runtime.ts";
import { parseLedger } from "../session-trail-footer/trail-state.ts";

const REQUIRED_COLUMNS = ["piece_id", "workspace_id", "agent_name", "pane_id", "agent_watch_id", "armed_at"] as const;

export interface LedgerOwner {
  workspaceId: string;
  paneId: string;
}

export interface OrchestrationLedger {
  path: string;
  rows: Record<string, string>[];
}

export type WatchGateResult = { ok: true } | { ok: false; reason: string };

export async function validateOrchestrationLedger(path: string, owner: LedgerOwner): Promise<OrchestrationLedger> {
  if (!isAbsolute(path)) throw new Error("orchestration ledger path must be absolute");
  const parsed = parseLedger(await readFile(path, "utf8"));
  if (!parsed) throw new Error("orchestration ledger has no valid piece_id CSV header");
  const workspace = headerValue(parsed.preamble, "orchestrator_workspace_id");
  const pane = headerValue(parsed.preamble, "orchestrator_pane_id");
  if (workspace !== owner.workspaceId || pane !== owner.paneId) {
    throw new Error(`orchestration ledger owner must be ${owner.workspaceId}/${owner.paneId}`);
  }
  for (const column of REQUIRED_COLUMNS) {
    if (!parsed.columns.includes(column)) throw new Error(`orchestration ledger is missing required column ${column}`);
  }
  const pieces = new Set<string>();
  const rows = parsed.rows.map((cells) => Object.fromEntries(parsed.columns.map((column, index) => [column, cells[index] ?? ""])));
  for (const row of rows) {
    if (!row.piece_id) throw new Error("orchestration ledger contains an empty piece_id");
    if (pieces.has(row.piece_id)) throw new Error(`orchestration ledger contains duplicate piece_id ${row.piece_id}`);
    pieces.add(row.piece_id);
  }
  return { path, rows };
}

export async function inspectWatchGate(
  path: string,
  owner: LedgerOwner,
  pending: { workspaceId: string; paneId: string },
  lookup: (id: string) => HerdrAgentMonitorState | undefined,
): Promise<WatchGateResult> {
  let ledger: OrchestrationLedger;
  try {
    ledger = await validateOrchestrationLedger(path, owner);
  } catch (error) {
    return { ok: false, reason: errorMessage(error) };
  }
  const matches = ledger.rows.filter((row) => row.workspace_id === pending.workspaceId);
  if (matches.length !== 1) return { ok: false, reason: `created workspace ${pending.workspaceId} is not recorded exactly once in the orchestration ledger` };
  const row = matches[0];
  if (row.pane_id !== pending.paneId) return { ok: false, reason: `piece ${row.piece_id} pane does not match created pane ${pending.paneId}` };
  if (!row.agent_name) return { ok: false, reason: `piece ${row.piece_id} has no agent_name` };
  if (!row.agent_watch_id) return { ok: false, reason: `piece ${row.piece_id} has no agent_watch_id` };
  if (!isIsoTime(row.armed_at)) return { ok: false, reason: `piece ${row.piece_id} has no valid armed_at` };
  const monitor = lookup(row.agent_watch_id);
  if (monitor === undefined) return { ok: false, reason: `piece ${row.piece_id} agent_watch_id ${row.agent_watch_id} does not exist in this Pi session` };
  if (monitor.agent !== row.agent_name) return { ok: false, reason: `piece ${row.piece_id} monitor agent mismatch: ledger=${row.agent_name}, monitor=${monitor.agent}` };
  if (monitor.armedAt !== row.armed_at) return { ok: false, reason: `piece ${row.piece_id} monitor arming timestamp mismatch: ledger=${row.armed_at}, monitor=${monitor.armedAt}` };
  if (monitor.phase === "running") return { ok: true };
  if (monitor.phase === "exited" && monitor.inspection?.classification === "complete") return { ok: true };
  if (monitor.phase === "exited") return { ok: false, reason: `piece ${row.piece_id} monitor ${monitor.id} exited but was not inspected as complete` };
  return { ok: false, reason: `piece ${row.piece_id} monitor ${monitor.id} is ${monitor.phase}` };
}

function headerValue(preamble: string, key: string): string | undefined {
  const matches = preamble.split("\n").filter((line) => line.startsWith(`${key}:`));
  return matches.length === 1 ? matches[0].slice(key.length + 1).trim() : undefined;
}

function isIsoTime(value: string): boolean {
  return /^\d{4}-\d\d-\d\dT/.test(value) && Number.isFinite(Date.parse(value));
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

import { spawn as nodeSpawn } from "node:child_process";
import { StringEnum } from "@earendil-works/pi-ai";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { inspectWatchGate, validateOrchestrationLedger, type LedgerOwner } from "./ledger.ts";
import { createHerdrAgentMonitorRuntime, type HerdrAgentMonitorRuntime, type HerdrAgentMonitorState, type HerdrAgentWaitStatus, type SpawnedChild } from "./runtime.ts";
import { localWorktreeCreateCount, parseWorktreeCreationReceipt } from "../session-trail-footer/ownership-receipts.ts";

interface ExtensionOptions {
  runtime?: HerdrAgentMonitorRuntime;
  owner?: LedgerOwner;
}

type PendingCreation = { workspaceId: string; paneId: string } | { error: string };

export default function herdrAgentMonitor(pi: ExtensionAPI, options: ExtensionOptions = {}): void {
  const owner = options.owner ?? {
    workspaceId: process.env.HERDR_WORKSPACE_ID ?? "",
    paneId: process.env.HERDR_PANE_ID ?? "",
  };
  const runtime = options.runtime ?? createHerdrAgentMonitorRuntime({
    spawn: (command, args, spawnOptions) => nodeSpawn(command, args, spawnOptions) as unknown as SpawnedChild,
    exec: (command, args) => pi.exec(command, args).then(({ stdout, stderr, code }) => ({ stdout, stderr, code })),
    send: (message, sendOptions) => pi.sendMessage(message, sendOptions),
  });
  let ledgerPath: string | undefined;
  let pending: PendingCreation | undefined;

  pi.on("tool_call", async (event) => {
    if (ledgerPath === undefined || event.toolName !== "bash") return;
    const command = commandInput(event.input);
    const creations = localWorktreeCreateCount(command);
    if (creations === 0) return;
    if (creations !== 1) return { block: true, reason: "Explicit orchestration permits one herdr worktree create per Bash call so its watch receipt can be verified." };
    const failure = await pendingFailure(ledgerPath, owner, pending, runtime);
    return failure === undefined ? undefined : { block: true, reason: failure };
  });

  pi.on("tool_result", (event) => {
    if (ledgerPath === undefined || event.toolName !== "bash" || localWorktreeCreateCount(commandInput(event.input)) !== 1) return;
    const structured = event.structuredContent as { exit_code?: number; truncated?: boolean } | undefined;
    const details = event.details as { truncation?: { truncated?: boolean } } | undefined;
    if (event.isError || (structured?.exit_code !== undefined && structured.exit_code !== 0)) return;
    if (structured?.truncated === true || details?.truncation?.truncated === true) {
      pending = { error: "The successful Herdr worktree creation receipt was truncated; record and verify the created workspace before further dispatch." };
      return;
    }
    const output = event.content.filter((item) => item.type === "text").map((item) => item.text).join("\n");
    pending = parseWorktreeCreationReceipt(output)
      ?? { error: "The successful Herdr worktree creation receipt was ambiguous; record and verify the created workspace before further dispatch." };
  });

  pi.on("session_shutdown", () => {
    runtime.shutdown();
    ledgerPath = undefined;
    pending = undefined;
  });

  pi.registerTool({
    name: "herdr_agent_monitor",
    label: "Herdr Agent Monitor",
    description: "Run one parent-owned event-driven Herdr agent wait, retain its receipt/result, and guard explicitly registered orchestration against unwatched next launches.",
    executionMode: "sequential",
    parameters: Type.Object({
      action: StringEnum(["begin", "add", "list", "status", "ack", "stop", "end"] as const),
      ledger: Type.Optional(Type.String()),
      agent: Type.Optional(Type.String()),
      timeoutMs: Type.Optional(Type.Integer({ minimum: 1_000, maximum: 86_400_000 })),
      until: Type.Optional(Type.Array(StringEnum(["idle", "working", "blocked", "done"] as const), { minItems: 1, uniqueItems: true })),
      id: Type.Optional(Type.String()),
      classification: Type.Optional(StringEnum(["complete"] as const)),
    }),
    async execute(_toolCallId, params) {
      try {
        if (params.action === "begin") {
          if (ledgerPath !== undefined) throw new Error(`orchestration guard is already active for ${ledgerPath}`);
          if (!params.ledger) throw new Error("begin requires ledger");
          requireOwner(owner);
          const ledger = await validateOrchestrationLedger(params.ledger, owner);
          ledgerPath = ledger.path;
          pending = undefined;
          return result(`orchestration watch guard active for ${ledger.path}`);
        }
        if (params.action === "add") {
          if (!params.agent || params.timeoutMs === undefined) throw new Error("add requires agent and timeoutMs");
          return result(formatState(await runtime.add({ agent: params.agent, timeoutMs: params.timeoutMs, until: params.until as HerdrAgentWaitStatus[] | undefined })));
        }
        if (params.action === "list") {
          const states = runtime.list();
          return result(states.length === 0 ? "no Herdr agent monitors" : states.map(formatState).join("\n"));
        }
        if (params.action === "status") {
          if (!params.id) throw new Error("status requires id");
          const state = runtime.status(params.id);
          if (!state) throw new Error(`monitor not found: ${params.id}`);
          return result(formatState(state, true));
        }
        if (params.action === "ack") {
          if (!params.id || params.classification !== "complete") throw new Error("ack requires id and classification=complete");
          return result(formatState(await runtime.ack(params.id, { classification: params.classification })));
        }
        if (params.action === "stop") {
          if (!params.id) throw new Error("stop requires id");
          return result(runtime.stop(params.id) ? `monitor stopped: ${params.id}` : `monitor not found: ${params.id}`);
        }
        if (params.action === "end") {
          if (ledgerPath === undefined) return result("orchestration watch guard is not active");
          const failure = await pendingFailure(ledgerPath, owner, pending, runtime);
          if (failure !== undefined) throw new Error(failure);
          const ended = ledgerPath;
          ledgerPath = undefined;
          pending = undefined;
          return result(`orchestration watch guard ended for ${ended}`);
        }
        throw new Error("invalid action");
      } catch (error) {
        return { ...result(errorMessage(error)), isError: true };
      }
    },
  });
}

async function pendingFailure(path: string, owner: LedgerOwner, pending: PendingCreation | undefined, runtime: HerdrAgentMonitorRuntime): Promise<string | undefined> {
  if (pending === undefined) return undefined;
  if ("error" in pending) return pending.error;
  const gate = await inspectWatchGate(path, owner, pending, (id) => runtime.status(id));
  return gate.ok ? undefined : `Dispatch blocked: ${gate.reason}. Record the monitor receipt before another launch.`;
}

function formatState(state: HerdrAgentMonitorState, verbose = false): string {
  const summary = `${state.id} agent=${state.agent} phase=${state.phase} armed_at=${state.armedAt} timeout_ms=${state.timeoutMs} until=${state.until.join("|")} classification=${state.inspection?.classification ?? "uninspected"}`;
  if (!verbose) return summary;
  return `${summary} completed_at=${state.completedAt ?? "none"} exit=${state.exitCode ?? "none"} signal=${state.signal ?? "none"} error=${state.error ?? "none"}\nstdout:\n${state.stdout || "<empty>"}\nstderr:\n${state.stderr || "<empty>"}`;
}

function requireOwner(owner: LedgerOwner): void {
  if (!/^[A-Za-z0-9_-]+$/.test(owner.workspaceId) || !owner.paneId.startsWith(`${owner.workspaceId}:`)) {
    throw new Error("begin requires a valid current Herdr workspace and pane");
  }
}

function commandInput(input: unknown): string {
  return typeof input === "object" && input !== null && typeof (input as { command?: unknown }).command === "string"
    ? (input as { command: string }).command
    : "";
}

function result(text: string) {
  return { content: [{ type: "text" as const, text }], details: undefined };
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

